# [door-fee-meta] (2026-11-13): the fork row test_Matriz_DaiEPortaExata (test/fork/FidelityMatrix.t.sol)
# asks the exact door for 1 bps of the delivery in the same block; its offline twin
# (test/ExactDoorFollowsTheFeeCalendar.t.sol) asks for equality. The fork row skips without DRPC_KEY,
# so no mutant of it can be killed here: this tripwire refuses a widened fork tolerance instead.
_FORK_ROW = "test/fork/FidelityMatrix.t.sol"
if os.path.exists(_FORK_ROW) and "assertLe((entregue - exactOut) * 10_000, exactOut," not in open(_FORK_ROW).read():
    sys.exit("[door-fee-meta] " + _FORK_ROW + ": the exact-door row no longer asks for 1 bps; "
             "the offline twin test/ExactDoorFollowsTheFeeCalendar.t.sol asserts equality")

# The gas ledgers in test/gas/ pin their numbers in snapshots/<test>.json (one group per test, named
# after it), and a mutant that only costs gas fails nothing but that comparison. So every run checks
# the committed snapshots, and none rewrites them: a run that wrote would turn a difference it missed
# into the pristine value of every later run.
SNAPSHOT_FLAGS = ["--gas-snapshot-check", "true", "--gas-snapshot-emit", "false"]
ANSI = re.compile(r"\x1b\[[0-9;]*m")


def run(t):
    r = subprocess.run(["forge","test","--match-test",t] + SNAPSHOT_FLAGS,
                       capture_output=True, text=True,
                       env={**os.environ,"FOUNDRY_PROFILE":"release"})
    return r.returncode == 0, ANSI.sub("", r.stdout + r.stderr)


def named_failure(t, out):
    """Whether the output names the failure of test t: its own [FAIL] line, a failed setUp of the
    contract the run selected, or its own snapshot group differing.

    A snapshot difference fails the run as a whole while every test prints [PASS], and so do a
    difference in another group, a crash and an OOM: the exit code alone says nothing about which
    test caught what. A test that owns a snapshot group is credited with a kill only when this
    holds."""
    for line in out.splitlines():
        s = line.strip()
        if s.startswith("[FAIL") and (f"] {t}(" in s or "] setUp(" in s):
            return True
        if s.startswith(f"[{t}] Failed to match snapshots"):
            return True
    return False


def artefact_fingerprint(harness=()):
    """sha256 of each shipped contract's DEPLOYED bytecode, and of every artefact of the harness files.

    A mutant is a claim about the artefact, not about the source. A source edit the optimiser
    folds away compiles to a byte-identical object: the paired test then passes for the same
    reason it always passed, the mutant is scored DECORATIVE, and the verdict is about nothing.
    The reverse is worse - a mutant scored killed while the artefact never moved would be
    counted as evidence for a guard the run never exercised.

    So the guard now reads what decides. Byte-identical artefact means the mutant is inert and
    its verdict is discarded rather than reported. (Owner's point, 2026-09-04: run the mutants
    against the bytecode too, or there is no certainty.)

    A mutant on a test file (the hyp-1020 entries on DirtyWorld and Fix1020DelegatedCallbacks) is a
    claim about the harness, and it moves no shipped artefact: hashed against src alone, every one
    of them read INERT by construction from 2026-10-20 to 10-27, and fifteen guards on the harness
    were unread. `harness` names the non-src files a run mutates; every artefact compiled from them
    is hashed too, so a harness mutant is inert only when its own objects did not move."""
    out = {}
    # adapters: the Gate adapters are shipped artefacts too.
    for c in ("Core", "Quoter", "Solver", "Math", "Router", "Hub", "Gate",
              "AdapterCurveNG", "AdapterBalancerV2", "AdapterBalancerV3", "AdapterCurveCryptoNG"):
        f = os.path.join("out", f"BlazePhoenix{c}.sol", f"BlazePhoenix{c}.json")
        if not os.path.exists(f):
            return {}
        art = json.load(open(f))
        # Creation AND runtime: a constant used only by a constructor (PERMIT2_DEFAULT) lives
        # in the creation object alone, and a runtime-only hash is blind to a mutant on it.
        obj = art.get("bytecode", {}).get("object", "") + "|" + art.get("deployedBytecode", {}).get("object", "")
        out[c] = hashlib.sha256(obj.encode()).hexdigest()[:16]
    for f in harness:
        d = os.path.join("out", os.path.basename(f))
        for j in sorted(os.listdir(d)) if os.path.isdir(d) else ():
            art = json.load(open(os.path.join(d, j)))
            obj = art.get("bytecode", {}).get("object", "") + "|" + art.get("deployedBytecode", {}).get("object", "")
            out[f + ":" + j] = hashlib.sha256(obj.encode()).hexdigest()[:16]
    return out


def baseline():
    """Which paired tests are GREEN before anything is mutated.

    Killing a mutant is a two-sided claim - the test passed, then the mutation made it fail -
    and only the second side was ever checked here. Any test that is red for a reason of its
    own scores every mutant pinned to it as killed, for free and for ever, and this repository
    has carried a red test for weeks without noticing (two, in the fork job, found on
    2026-09-04). Today no mutant is pinned to one: all 151 paired names exist, resolve to
    exactly one test each, and none lives in test/fork/. That is a fact about today, not a
    property, which is why it is now measured on every run instead of assumed.

    One suite run, in the same profile the mutants use, so the baseline and the verdict cannot
    disagree about which binary they are talking about.

    A gas ledger whose committed snapshot no longer matches is red too, although every assert
    passed: forge prints [PASS] for it, names its group, and fails the run as a whole."""
    r = subprocess.run(["forge", "test"] + SNAPSHOT_FLAGS, capture_output=True, text=True,
                       env={**os.environ, "FOUNDRY_PROFILE": "release"})
    out = ANSI.sub("", r.stdout + r.stderr)
    green = set(re.findall(r"\[PASS\]\s+(\w+)", out))
    red = set(re.findall(r"\[FAIL[^\]]*\]\s+(\w+)", out))
    red |= set(re.findall(r"^\s*\[(\w+)\] Failed to match snapshots", out, re.M))
    return green, red, out, r.returncode

def shard():
    """(k, n): run the mutants whose 1-based index i has (i - 1) % n == k.

    The guard grows with every guarded fix - 231 mutants took ~50 minutes on 2026-09-22 and
    ~271 crossed the 90-minute ceiling of the job they shared on 2026-10-07 - so CI runs it as n
    parallel shards. Every shard checks its own mutants' targets and its own paired tests at
    baseline, so the union of the shards is the whole list, checked exactly once."""
    k = int(os.environ.get("MUTANTS_SHARD", "0"))
    n = int(os.environ.get("MUTANTS_SHARDS", "1"))
    if n < 1 or not 0 <= k < n:
        sys.exit(f"MUTANTS_SHARD={k} MUTANTS_SHARDS={n}: need 0 <= shard < shards")
    return k, n


def main():
    falhas = []
    k, n = shard()
    mine = [(i, m) for i, m in enumerate(M, 1) if (i - 1) % n == k]
    paired = {m["teste"] for _, m in mine}
    green, red, base_out, base_rc = baseline()
    if base_rc != 0 and not red:
        # A run that fails while naming no failed test and no snapshot group (a snapshot error with
        # no group, a crash, an OOM) clears nothing: a test it printed as [PASS] may be the cause.
        falhas.append(f"BASELINE FAILED: the unmutated suite exited {base_rc} and names no failed test "
                      f"or snapshot group, so no paired test can be cleared as green.")
        print(f"  BASELINE ?    exit {base_rc}, nothing named")
    # `inl`: a harness file that is a library of internal functions (test/ref/Frame4007.sol) has an
    # artefact of its own that never moves; its code is inlined into the importer named by `inl`,
    # whose artefacts are hashed under the mutant's own prefix (read INERT by construction, 2026-11-12).
    harness = sorted({f for _, m in mine for f in (m["f"], m.get("inl")) if f and not f.startswith("src/")})
    pristine = artefact_fingerprint(harness)
    # A test file is recompiled only by the runs whose test it holds, so its objects stay as the last
    # mutant on it left them: each mutant is judged on src plus its own file, never on another's.
    own = lambda d, m: {k: v for k, v in d.items() if ":" not in k or k.startswith(m["f"] + ":")
                        or (m.get("inl") and k.startswith(m["inl"] + ":"))}
    inert = []
    unseen = paired - green - red
    if red & paired:
        for t in sorted(red & paired):
            falhas.append(f"BASELINE RED: '{t}' already fails with no mutation, so every mutant "
                          f"paired with it scores as killed for free and proves nothing.")
            print(f"  BASELINE RED  {t}")
    if unseen:
        for t in sorted(unseen):
            falhas.append(f"BASELINE MISSING: '{t}' appeared as neither PASS nor FAIL in the "
                          f"baseline run, so whether it can fail at all is unknown.")
            print(f"  BASELINE ?    {t}")
    for i, m in mine:
        src = open(m["f"]).read()
        if src.count(m["old"]) != 1:
            falhas.append(f"[{i}] {m['nome']}: the mutant target does not exist (or there are several) in {m['f']}. "
                          f"The code changed and this list was not updated.")
            print(f"  [{i}] TARGET LOST  {m['nome']}"); continue
        bak = src
        try:
            open(m["f"],"w").write(src.replace(m["old"], m["new"]))
            ok, out = run(m["teste"])
            fp = artefact_fingerprint(harness)
            if pristine and fp and own(fp, m) == own(pristine, m):
                # The source moved and the artefact did not. Whatever the test did, it did not
                # do it because of this mutant.
                inert.append(f"[{i}] {m['nome']}: INERT - the deployed bytecode is byte-identical "
                             f"to pristine, so this mutant exercises nothing.")
                print(f"  [{i}] INERT        {m['nome']}  (artefact unchanged)")
            elif ok:
                falhas.append(f"[{i}] {m['nome']}: the test '{m['teste']}' PASSED with the guard mutated. "
                              f"The guard is unwatched - the test is decorative.")
                print(f"  [{i}] DECORATIVE   {m['nome']}  ({m['teste']} passou mutado)")
            elif "No tests match" in out or "Compiler run failed" in out:
                falhas.append(f"[{i}] {m['nome']}: the test '{m['teste']}' does not exist.")
                print(f"  [{i}] TEST MISSING {m['nome']}")
            elif (os.path.exists(os.path.join("snapshots", m["teste"] + ".json"))
                  and not named_failure(m["teste"], out)):
                falhas.append(f"[{i}] {m['nome']}: the run of '{m['teste']}' failed, but the output names "
                              f"neither that test failing nor its own snapshot group differing, so the "
                              f"kill is not evidence.")
                print(f"  [{i}] NO EVIDENCE  {m['nome']}")
            else:
                print(f"  [{i}] ok           {m['nome']}")
        finally:
            open(m["f"],"w").write(bak)
    print()
    if inert:
        print("INERT MUTANTS (the artefact never moved, so their verdict means nothing):")
        for f in inert: print("  -", f)
        falhas.extend(inert)
    if falhas:
        print("UNWATCHED GUARDS:"); [print("  -", f) for f in falhas]
        sys.exit(1)
    print(f"{len(mine)}/{len(mine)} guards with a test that catches them (shard {k + 1}/{n} of {len(M)}), "
          f"all green at baseline ({len(green)} passing tests).")

if __name__ == "__main__":
    main()
